public function applyClientScope(Builder $query, ?User $user, array $bypassPermissions = []): Builder
{
    $siteIds = $this->accessibleSiteIds($user, $bypassPermissions);
    if ($siteIds === []) {
        return $query->whereRaw('1 = 0');
    }

    return $query->whereIn('site_id', $siteIds);
}

/**
 * @param  array<int, string>  $bypassPermissions
 */

public function accessibleSiteIds(?User $user, array $bypassPermissions = []): array
{
    $cacheKey = implode('|', [
        $user ? (string) ($user->getKey() ?? 'unsaved') : 'guest',
        $user ? (string) spl_object_id($user) : 'guest',
        implode(',', $bypassPermissions),
    ]);
    if (array_key_exists($cacheKey, $this->accessibleSiteIdsCache)) {
        return $this->accessibleSiteIdsCache[$cacheKey];
    }

    if (! $user) {
        return $this->accessibleSiteIdsCache[$cacheKey] = [];
    }

    if ($this->canBypass($user, $bypassPermissions)) {
        return $this->accessibleSiteIdsCache[$cacheKey] = Site::query()
            ->active()
            ->notArchived()
            ->whereNull('archived_at')
            ->orderBy('id')
            ->pluck('id')
            ->map(fn ($siteId) => (int) $siteId)
            ->all();
    }

    $user->loadMissing('hrEmployeeProfile');

    $profile = $user->hrEmployeeProfile;
    if (! $profile || ! $this->isCurrentEmployeeProfile($profile)) {
        return $this->accessibleSiteIdsCache[$cacheKey] = [];
    }

    $secondarySiteIds = is_array($profile?->secondary_site_ids)
        ? $profile->secondary_site_ids
        : [];

    $assignedSiteIds = collect([
        $profile?->primary_site_id,
        ...$secondarySiteIds,
    ])
        ->filter(fn ($siteId) => filled($siteId))
        ->map(fn ($siteId) => (int) $siteId)
        ->filter(fn (int $siteId) => $siteId > 0)
        ->unique()
        ->values()
        ->all();

    if ($assignedSiteIds === []) {
        return $this->accessibleSiteIdsCache[$cacheKey] = [];
    }

    $currentSiteIds = Site::query()
        ->active()
        ->notArchived()
        ->whereNull('archived_at')
        ->whereIn('id', $assignedSiteIds)
        ->pluck('id')
        ->map(fn ($siteId) => (int) $siteId)
        ->all();

    return $this->accessibleSiteIdsCache[$cacheKey] = array_values(array_filter(
        $assignedSiteIds,
        fn (int $siteId) => in_array($siteId, $currentSiteIds, true),
    ));
}

/**
 * @param  array<int, string>  $bypassPermissions
 */

public function canBypass(?User $user, array $bypassPermissions = []): bool
{
    if (! $user) {
        return false;
    }

    foreach ($bypassPermissions as $permission) {
        if ($user->canDo($permission)) {
            return true;
        }
    }

    return false;
}

/** @return array<int, int> */

public function canDo(string $permissionKey): bool
{
    $permissionKeys = $this->permissionLookupKeys($permissionKey);

    if ($this->relationLoaded('permissionOverrides')
        && $this->relationLoaded('roles')
        && $this->roles->every(fn (Role $role) => $role->relationLoaded('permissions'))) {
        $overrides = $this->permissionOverrides
            ->filter(fn (Permission $permission) => in_array($permission->key, $permissionKeys, true));

        if ($overrides->contains(fn (Permission $permission) => ! (bool) $permission->pivot->allowed)) {
            return false;
        }

        if ($overrides->contains(fn (Permission $permission) => (bool) $permission->pivot->allowed)) {
            return true;
        }

        return $this->roles->contains(
            fn (Role $role) => $role->permissions->contains(
                fn (Permission $permission) => in_array($permission->key, $permissionKeys, true),
            ),
        );
    }

    // 1) explicit deny override wins
    $deny = $this->permissionOverrides()
        ->whereIn('permissions.key', $permissionKeys)
        ->wherePivot('allowed', false)
        ->exists();

    if ($deny) {
        return false;
    }

    // 2) explicit allow override
    $allow = $this->permissionOverrides()
        ->whereIn('permissions.key', $permissionKeys)
        ->wherePivot('allowed', true)
        ->exists();

    if ($allow) {
        return true;
    }

    // 3) role permissions
    return $this->roles()
        ->whereHas('permissions', fn ($q) => $q->whereIn('key', $permissionKeys))
        ->exists();
}

/**
 * Legacy permission keys kept as policy-layer synonyms while routes and
 * controllers use the canonical namespace.
 *
 * @return list<string>
 */

public function index(Request $request)
{
    $orgId = self::APPLICATION_STORAGE_CONTEXT_ID;

    $query = FinInvoice::forOrganization($orgId)
        // Lines power the in-place Edit modal's prefill for draft invoices.
        ->with('lines:id,invoice_id,description,quantity,unit_price,tax_rate_id,account_id')
        ->orderBy('invoice_date', 'desc');

    if ($request->filled('status')) {
        $query->ofStatus($request->input('status'));
    }

    if ($request->filled('search')) {
        $search = $request->input('search');
        $query->where(function ($q) use ($search) {
            $q->where('invoice_number', 'like', "%{$search}%")
                ->orWhere('client_name', 'like', "%{$search}%")
                ->orWhere('client_email', 'like', "%{$search}%");
        });
    }

    if ($request->filled('q')) {
        $search = $request->input('q');
        $query->where(function ($q) use ($search) {
            $q->where('invoice_number', 'like', "%{$search}%")
                ->orWhere('client_name', 'like', "%{$search}%")
                ->orWhere('funding_body', 'like', "%{$search}%");
        });
    }

    if ($request->filled('client_id')) {
        $query->where('client_id', $request->integer('client_id'));
    }

    if ($request->filled('date_from')) {
        $query->where('invoice_date', '>=', $request->input('date_from'));
    }

    if ($request->filled('date_to')) {
        $query->where('invoice_date', '<=', $request->input('date_to'));
    }

    $invoices = $query->paginate(20)->withQueryString();

    // Attach the outstanding balance to each row (one grouped query, no N+1) so
    // the Record-Receipt modal can default + cap the receipt amount.
    $pageIds = collect($invoices->items())->pluck('id');
    $paidById = FinPaymentAllocation::where('allocatable_type', FinInvoice::class)
        ->whereIn('allocatable_id', $pageIds)
        ->groupBy('allocatable_id')
        ->selectRaw('allocatable_id, SUM(amount) as total_paid')
        ->pluck('total_paid', 'allocatable_id');
    $invoices->through(function (FinInvoice $invoice) use ($paidById) {
        $paid = (float) ($paidById[$invoice->id] ?? 0);
        $invoice->amount_paid = round($paid, 2);
        $invoice->amount_due = round((float) $invoice->total_amount - $paid, 2);

        return $invoice;
    });

    $allInvoices = FinInvoice::forOrganization($orgId)->get();
    $summary = [
        'total_outstanding' => $allInvoices->whereIn('status', ['sent', 'viewed', 'overdue'])->sum('total_amount'),
        'total_overdue' => $allInvoices->where('status', 'overdue')->sum('total_amount'),
        'draft_count' => $allInvoices->where('status', 'draft')->count(),
        'paid_this_month' => $allInvoices->where('status', 'paid')
            ->where('paid_at', '>=', now()->startOfMonth())->sum('total_amount'),
    ];

    $canManage = (bool) $request->user()?->canDo('finance.ar.manage');

    return Inertia::render('finance/invoices/Index', [
        'invoices' => $invoices,
        'filters' => $request->only(['status', 'search', 'date_from', 'date_to']),
        'summary' => $summary,
        'canManage' => $canManage,
        // Reference data for the New Invoice modal — only for managers (the
        // create route is finance.ar.manage), so view-only users skip the queries.
        'clients' => $canManage
            ? $this->clientOptions($request->user())
                ->map(fn ($c) => ['id' => $c->id, 'name' => trim($c->first_name.' '.$c->last_name)])
                ->values()
            : [],
        'taxRates' => $canManage
            ? FinTaxRate::forOrganization($orgId)->active()->orderBy('name')->get(['id', 'name', 'rate'])
            : [],
    ]);
}

/**
 * Stream the (filtered) invoice list as a sanitised CSV. Honours the same
 * status/search/date filters as the index so "Export" respects the current view.
 */

private function accessibleClients(User $user): Builder
{
    return app(UserSiteAccessService::class)->applyClientScope(
        Client::query(),
        $user,
        ['reports.viewAny'],
    );
}
